test('signed-out startup validates inputs without making an authentication request',async()=>{const {w,dom,calls}=await setup(false);w.document.getElementById('signin').click();await tick();assert.match(w.document.getElementById('authmsg').textContent,/valid email/);assert.equal(calls.length,0);dom.window.close()});
test('signed-in inbox escapes names and opens a conversation by keyboard-accessible button',async()=>{const {w,dom}=await setup();assert.ok(w.document.getElementById('home').classList.contains('active'));const row=w.document.querySelector('button.chatrow');assert.ok(row);assert.equal(row.querySelectorAll('img').length,0);row.click();await tick();assert.ok(w.document.getElementById('room').classList.contains('active'));assert.match(w.document.getElementById('roomtitle').textContent,/<img/);dom.window.close()});
test('failed sends preserve draft and retry the same operation instead of duplicating it',async()=>{const {w,dom,calls}=await setup();w.document.querySelector('.chatrow').click();await tick();const body=w.document.getElementById('body'),form=w.document.getElementById('sendform');body.value='Keep this draft';form.dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(body.value,'Keep this draft');assert.equal(body.disabled,false);form.dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();const sends=calls.filter(c=>c.name==='send_chat_message_idempotent');assert.equal(sends.length,2);assert.equal(sends[0].args.operation_id,sends[1].args.operation_id);assert.equal(body.value,'');assert.match(w.document.getElementById('messages').textContent,/Keep this draft/);dom.window.close()});
test('recovery event shows the recovery form and signout clears cached conversation content',async()=>{const {w,dom,event}=await setup();event('PASSWORD_RECOVERY');assert.ok(w.document.getElementById('recovery').classList.contains('active'));w.document.getElementById('messages').textContent='Private history';event('SIGNED_OUT');assert.equal(w.document.getElementById('messages').textContent,'');assert.ok(w.document.getElementById('auth').classList.contains('active'));dom.window.close()});
test('saved message control updates its accessible state after server confirmation',async()=>{const {w,dom,calls}=await setup(true,true);w.document.querySelector('.chatrow').click();await tick();const save=w.document.querySelector('[data-save]');assert.ok(save);save.click();await tick();assert.equal(save.textContent,'Unsave');assert.equal(save.getAttribute('aria-pressed'),'true');assert.equal(calls.find(c=>c.name==='set_chat_bookmark').args.should_save,true);dom.window.close()});
test('reactions target the correct message and do not inject executable markup',async()=>{const {w,dom,calls}=await setup(true,true);w.document.querySelector('.chatrow').click();await tick();const reaction=[...w.document.querySelectorAll('.extra-actions button')].find(b=>b.textContent==='❤️');reaction.click();await tick();const sent=calls.find(c=>c.name==='toggle_chat_reaction');assert.equal(sent.args.reaction,'❤️');assert.equal(sent.args.target_message_id,'55555555-5555-4555-8555-555555555555');dom.window.close()});
test('scheduling converts local time to an absolute instant and clears draft after acceptance',async()=>{const {w,dom,calls}=await setup();w.document.querySelector('.chatrow').click();await tick();w.document.getElementById('body').value='Send this tomorrow';w.document.getElementById('scheduleText').click();assert.ok(w.document.getElementById('scheduleDialog').hasAttribute('open'));const when=w.document.getElementById('scheduledTime').value;w.document.getElementById('scheduleForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();const schedule=calls.find(c=>c.name==='schedule_chat_text');assert.equal(schedule.args.scheduled_for,new Date(when).toISOString());assert.equal(schedule.args.message_body,'Send this tomorrow');assert.equal(w.document.getElementById('body').value,'');dom.window.close()});
test('Shift+Enter preserves multiline composing and font settings apply only after a saved preference',async()=>{const {w,dom,calls}=await setup();w.document.querySelector('.chatrow').click();await tick();const body=w.document.getElementById('body'),event=new w.KeyboardEvent('keydown',{key:'Enter',shiftKey:true,cancelable:true});body.dispatchEvent(event);assert.equal(event.defaultPrevented,false);assert.equal(calls.filter(c=>c.name==='send_chat_message_idempotent').length,0);w.document.getElementById('fontScale').value='1.4';w.document.getElementById('privacyForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(w.document.documentElement.style.getPropertyValue('--message-scale'),'1.4');assert.equal(calls.find(c=>c.name==='set_chat_privacy').args.text_scale,1.4);dom.window.close()});
test('poll creation validates unique choices before sending a request',async()=>{const {w,dom,calls}=await setup();w.document.querySelector('.chatrow').click();await tick();w.document.getElementById('createPoll').click();w.document.getElementById('pollQuestion').value='Choose a time';w.document.getElementById('pollOptions').value='Morning\nmorning';w.document.getElementById('pollForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.match(w.document.getElementById('pollStatus').textContent,/different options/);assert.equal(calls.filter(c=>c.name==='create_chat_simple_poll').length,0);w.document.getElementById('pollOptions').value='Morning\nEvening';w.document.getElementById('pollForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.deepEqual(Array.from(calls.find(c=>c.name==='create_chat_simple_poll').args.option_texts),['Morning','Evening']);dom.window.close()});

test('account modes expose signup fields and reject mismatched passwords before submission',async()=>{const {w,dom,calls}=await setup(false);const d=w.document;d.getElementById('authModeSignup').click();assert.equal(d.getElementById('username').classList.contains('hidden'),false);assert.equal(d.getElementById('signin').classList.contains('hidden'),true);d.getElementById('email').value='ui@example.invalid';d.getElementById('password').value='long-password';d.getElementById('username').value='valid_user';d.getElementById('signupConfirm').value='wrong-password';d.getElementById('signup').click();assert.match(d.getElementById('authmsg').textContent,/do not match/);assert.equal(calls.length,0);d.getElementById('authModeSignin').click();assert.equal(d.getElementById('password').autocomplete,'current-password');dom.window.close()});
test('password visibility control describes its state accessibly',async()=>{const {w,dom}=await setup(false);const d=w.document;d.getElementById('showPassword').click();assert.equal(d.getElementById('password').type,'text');assert.equal(d.getElementById('showPassword').getAttribute('aria-pressed'),'true');d.getElementById('showPassword').click();assert.equal(d.getElementById('password').type,'password');dom.window.close()});
test('desktop navigation keeps screen state consistent when leaving and returning to a room',async()=>{const {w,dom}=await setup();const d=w.document;d.querySelector('.chatrow').click();await tick();assert.equal(d.querySelector('.app').dataset.screen,'room');d.querySelector('[data-tab="profile"]').click();assert.equal(d.querySelector('.app').dataset.screen,'home');assert.equal(d.querySelector('.app').dataset.tab,'profile');d.querySelector('[data-tab="chats"]').click();assert.equal(d.querySelector('.app').dataset.screen,'room');assert.equal(d.querySelector('.app').dataset.tab,'chats');dom.window.close()});
test('keyboard shortcuts open actual search and compose views',async()=>{const {w,dom}=await setup();const d=w.document;d.dispatchEvent(new w.KeyboardEvent('keydown',{key:'k',ctrlKey:true,cancelable:true}));assert.equal(d.getElementById('globalSearchPanel').classList.contains('hidden'),false);assert.equal(d.activeElement.id,'globalSearchInput');d.dispatchEvent(new w.KeyboardEvent('keydown',{key:'n',ctrlKey:true,cancelable:true}));assert.equal(d.querySelector('.app').dataset.tab,'new');assert.equal(d.activeElement.id,'target');await tick();dom.window.close()});
test('mobile overflow menu retains poll, search, and pin controls',async()=>{const {w,dom}=await setup();const d=w.document;d.querySelector('.chatrow').click();await tick();[...d.querySelectorAll('.room-menu-items button')].find(b=>b.textContent==='Create a poll').click();assert.ok(d.getElementById('pollDialog').hasAttribute('open'));assert.ok(d.querySelector('[data-icon="chat"] svg'));assert.ok(d.querySelector('[data-icon="close"] svg'));dom.window.close()});
test('safe URLs become external links while markup stays inert',async()=>{const {w,dom,data}=await setup(true,true);data.chat_messages[0].body='Visit https://example.com/help?q=1 and <img src=x onerror=alert(1)>';w.document.querySelector('.chatrow').click();await tick();const body=w.document.querySelector('.bubble-body'),a=body.querySelector('a');assert.equal(a.href,'https://example.com/help?q=1');assert.match(a.rel,/noopener/);assert.equal(body.querySelectorAll('img').length,0);assert.match(body.textContent,/<img/);dom.window.close()});
test('shared files filter loaded names and MIME types and exclude recalled content',async()=>{const {w,dom,data,cid}=await setup(true,true);const m=data.chat_messages[0];data.chat_attachments=[{id:'f1',message_id:m.id,conversation_id:cid,file_name:'holiday.png',mime_type:'image/png',byte_size:100,chat_messages:m},{id:'f2',message_id:m.id,conversation_id:cid,file_name:'notes.pdf',mime_type:'application/pdf',byte_size:200,chat_messages:m},{id:'f3',message_id:'old',conversation_id:cid,file_name:'recalled.png',mime_type:'image/png',byte_size:100,chat_messages:{...m,recalled_at:new Date().toISOString()}}];const d=w.document;d.querySelector('.chatrow').click();await tick();d.getElementById('openMedia').click();await tick();assert.equal(d.querySelectorAll('#sharedList article').length,2);d.getElementById('mediaType').value='image/';d.getElementById('mediaType').dispatchEvent(new w.Event('change'));assert.equal(d.querySelectorAll('#sharedList article').length,1);assert.match(d.getElementById('sharedList').textContent,/holiday/);d.getElementById('mediaType').value='application/pdf';d.getElementById('mediaType').dispatchEvent(new w.Event('change'));assert.match(d.getElementById('sharedList').textContent,/notes.pdf/);assert.doesNotMatch(d.getElementById('sharedList').textContent,/holiday|recalled/);dom.window.close()});
test('signout clears new contact and shared content surfaces and closes dialogs',async()=>{const {w,dom,event}=await setup();const d=w.document;d.getElementById('contactList').textContent='Private contact';d.getElementById('sharedList').textContent='Private media';d.getElementById('sharedDialog').showModal();event('SIGNED_OUT');assert.equal(d.getElementById('contactList').textContent,'');assert.equal(d.getElementById('sharedList').textContent,'');assert.equal(d.querySelectorAll('dialog[open]').length,0);dom.window.close()});
test('black and gold is the default and touch composer shows its character count',async()=>{const {w,dom}=await setup();const d=w.document;assert.equal(d.body.classList.contains('light'),false);d.querySelector('.chatrow').click();await tick();const body=d.getElementById('body');body.value='Hello Luo';body.dispatchEvent(new w.Event('input'));assert.equal(d.getElementById('composerCount').textContent,'9 / 10,000');assert.equal(body.style.height,'44px');dom.window.close()});
test('install control appears only after the browser offers installation',async()=>{const {w,dom}=await setup(false);const d=w.document;assert.ok(d.getElementById('installApp').classList.contains('hidden'));let prompted=false;const e=new w.Event('beforeinstallprompt',{cancelable:true});e.prompt=async()=>{prompted=true};e.userChoice=Promise.resolve({outcome:'dismissed'});w.dispatchEvent(e);assert.equal(e.defaultPrevented,true);assert.equal(d.getElementById('installApp').classList.contains('hidden'),false);d.getElementById('installApp').click();await tick();assert.equal(prompted,true);w.dispatchEvent(new w.Event('appinstalled'));assert.match(d.getElementById('installHelp').textContent,/installed on this device/);dom.window.close()});
