test('turning Enter-to-send off preserves Enter as a newline',async()=>{const {w,dom,calls}=await setup();const d=w.document;d.querySelector('.chatrow').click();await tick();d.getElementById('enterToSend').checked=false;d.getElementById('enterToSend').dispatchEvent(new w.Event('change'));const e=new w.KeyboardEvent('keydown',{key:'Enter',cancelable:true});d.getElementById('body').dispatchEvent(e);assert.equal(e.defaultPrevented,false);assert.equal(calls.filter(x=>x.name==='send_chat_message_idempotent').length,0);dom.window.close()});
test('quiet-hour validation rejects invalid zones and equal times before server writes',async()=>{const {w,dom,calls}=await setup();const d=w.document;d.getElementById('quietZone').value='Invalid/Moon';d.getElementById('notificationPrefsForm').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.match(d.getElementById('notificationPrefsStatus').textContent,/valid time zone/);d.getElementById('quietZone').value='UTC';d.getElementById('quietEnabled').checked=true;d.getElementById('quietStart').value=d.getElementById('quietEnd').value='22:00';d.getElementById('notificationPrefsForm').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.match(d.getElementById('notificationPrefsStatus').textContent,/different/);assert.equal(calls.filter(x=>x.name==='set_my_notification_preferences').length,0);d.getElementById('quietEnd').value='08:00';d.getElementById('notificationPrefsForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(calls.find(x=>x.name==='set_my_notification_preferences').args.new_quiet_hours_end,'08:00');dom.window.close()});
test('clearing drafts affects only the signed-in account and clears the composer',async()=>{const {w,dom}=await setup();w.confirm=()=>true;const d=w.document;d.querySelector('.chatrow').click();await tick();w.localStorage.setItem('luo-chat-draft-11111111-1111-4111-8111-111111111111-room','mine');w.localStorage.setItem('luo-chat-draft-another-user-room','keep');d.getElementById('body').value='Unsent';d.getElementById('clearDrafts').click();assert.equal(w.localStorage.getItem('luo-chat-draft-another-user-room'),'keep');assert.equal(w.localStorage.getItem('luo-chat-draft-11111111-1111-4111-8111-111111111111-room'),null);assert.equal(d.getElementById('body').value,'');dom.window.close()});
test('other-device signout uses the others scope and preserves the local UI',async()=>{const {w,dom,calls}=await setup();w.confirm=()=>true;w.document.getElementById('signOutOthers').click();await tick();assert.equal(calls.find(x=>x.name==='auth:signOut').args.scope,'others');assert.equal(w.document.querySelector('.app').dataset.screen,'home');dom.window.close()});
test('new email requests require verification instead of overwriting the displayed address',async()=>{const {w,dom,calls}=await setup();const d=w.document,old=d.getElementById('myemail').textContent;d.getElementById('newEmail').value='new@example.invalid';d.getElementById('changeEmailForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(calls.find(x=>x.name==='auth:updateUser').args.email,'new@example.invalid');assert.equal(d.getElementById('myemail').textContent,old);assert.match(d.getElementById('emailChangeStatus').textContent,/until verification/);dom.window.close()});
test('upload usage filters to the owner and totals attachment bytes',async()=>{const {w,dom,data}=await setup();data.chat_attachments=[{id:'a',uploader_id:'11111111-1111-4111-8111-111111111111',byte_size:1048576,mime_type:'image/png'},{id:'b',uploader_id:'another-user',byte_size:9000000,mime_type:'video/mp4'}];w.document.getElementById('refreshStorage').click();await tick();assert.equal(w.document.getElementById('storageSummary').textContent,'1 shared file · 1.00 MB');dom.window.close()});

test('availability checklist opens and distinguishes encryption from implemented tools',async()=>{const {w,dom}=await setup();const d=w.document;d.getElementById('openFeatureChecklist').click();assert.ok(d.getElementById('workspaceDialog').open);assert.match(d.getElementById('workspaceBody').textContent,/End-to-end encryption — Not built/);assert.match(d.getElementById('workspaceBody').textContent,/Sentence replies — Implemented/);dom.window.close()});
test('sentence quote requires exact source text before updating the composer',async()=>{const {w,dom}=await setup(true,true);try{const d=w.document;d.querySelector('.chatrow').click();await tick();[...d.querySelectorAll('#messages button')].filter(b=>b.textContent==='Quote sentence').at(-1).click();await tick();d.getElementById('action-quote').value='invented sentence';d.getElementById('messageActionForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.match(d.getElementById('messageActionStatus').textContent,/exactly/);d.getElementById('action-quote').value='me saved';d.getElementById('messageActionForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(d.getElementById('messageActionDialog').open,false);assert.match(d.getElementById('replyBar').textContent,/me saved/);}finally{dom.window.close()}});
test('screen lock hides the app, requires reauthentication and clears on signout',async()=>{const {w,dom,event}=await setup();const d=w.document;d.getElementById('lockScreenNow').click();assert.ok(d.querySelector('.app').inert);assert.equal(d.getElementById('screenLock').classList.contains('hidden'),false);d.getElementById('screenLockPassword').value='password';d.getElementById('unlockScreenForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(d.querySelector('.app').inert,false);assert.equal(d.getElementById('screenLockPassword').value,'');d.getElementById('body').value='Private draft';event('SIGNED_OUT');assert.equal(d.getElementById('body').value,'');assert.equal(d.getElementById('screenLock').classList.contains('hidden'),true);dom.window.close()});


test('profile photos render in both the inbox and open chat and disappear after removal',async()=>{const photo='https://example.supabase.co/storage/v1/object/public/avatars/friend/photo.png';const {w,dom,data}=await setup(true,false,photo);try{const d=w.document;assert.equal(d.querySelector('.chatrow .avatar img').src,photo);assert.equal(d.querySelector('.chatrow .avatar').dataset.frame,'gold');d.querySelector('.chatrow').click();await tick();assert.equal(d.querySelector('#roomavatar img').src,photo);data.profiles[1].avatar_url=null;d.getElementById('back').click();await tick();assert.equal(d.querySelector('.chatrow .avatar img'),null);assert.ok(d.querySelector('.chatrow .avatar').textContent)}finally{dom.window.close()}});
test('reminder phrases must be applied and reviewed before saving the linked reminder',async()=>{const{w,dom,calls}=await setup(true,true);try{const d=w.document;d.querySelector('.chatrow').click();await tick();[...d.querySelectorAll('#messages button')].find(b=>b.textContent==='Remind me').click();await tick();d.getElementById('action-phrase').value='tomorrow at 3pm';d.getElementById('messageActionForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.match(d.getElementById('messageActionStatus').textContent,/Use time phrase/);assert.equal(calls.filter(c=>c.name==='insert:chat_reminders').length,0);[...d.querySelectorAll('#messageActionFields button')].find(b=>b.textContent==='Use time phrase').click();await tick();const value=d.getElementById('action-when').value;assert.ok(value.endsWith('T15:00'));d.getElementById('messageActionForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();const row=calls.find(c=>c.name==='insert:chat_reminders');assert.equal(row.args.remind_at,new Date(value).toISOString());assert.equal(row.args.message_id,'55555555-5555-4555-8555-555555555555')}finally{dom.window.close()}});
test('manual app update check explains unsupported browsers without clearing local data',async()=>{const{w,dom}=await setup();try{const d=w.document;w.localStorage.setItem('luo-chat-draft-test','keep me');d.getElementById('checkAppUpdate').click();await tick();assert.match(d.getElementById('appUpdateStatus').textContent,/does not support/);assert.equal(w.localStorage.getItem('luo-chat-draft-test'),'keep me');assert.equal(d.getElementById('checkAppUpdate').disabled,false)}finally{dom.window.close()}});


test('the tap action sheet reuses real reply and save handlers and clears after signout',async()=>{const{w,dom,calls,event}=await setup(true,true);try{const d=w.document;d.querySelector('.chatrow').click();await tick();d.querySelector('.message-extra-tools>summary').click();assert.equal(d.getElementById('messageActionSheet').open,true);[...d.querySelectorAll('#touchActionList button')].find(b=>b.textContent==='Reply').click();assert.equal(d.getElementById('replyBar').classList.contains('hidden'),false);d.querySelector('.message-extra-tools>summary').click();[...d.querySelectorAll('#touchActionList button')].find(b=>b.textContent==='Save').click();await tick();assert.equal(calls.find(c=>c.name==='set_chat_bookmark').args.should_save,true);d.querySelector('.message-extra-tools>summary').click();event('SIGNED_OUT');assert.equal(d.getElementById('messageActionSheet').open,false);assert.equal(d.getElementById('touchActionPreview').textContent,'')}finally{dom.window.close()}});


test('unvalidated recovery URL parameters cannot open password changes for an existing session',async()=>{for(const suffix of ['?auth=recovery','#type=recovery']){const {w,dom}=await setup(true,false,null,'https://luo-chat-luokai25.vercel.app/'+suffix);try{assert.equal(w.document.getElementById('recovery').classList.contains('active'),false);assert.equal(w.document.getElementById('home').classList.contains('active'),true)}finally{dom.window.close()}}});
test('a recovery event without a session cannot open password changes',async()=>{const {w,dom,event}=await setup(false);try{event('PASSWORD_RECOVERY',null);assert.equal(w.document.getElementById('recovery').classList.contains('active'),false)}finally{dom.window.close()}});
test('successful sign-in clears all password inputs and restores masked display',async()=>{const {w,dom}=await setup(false);try{const d=w.document;d.getElementById('email').value='ui@example.invalid';d.getElementById('password').value='test-only-password';d.getElementById('signupConfirm').value='test-only-password';d.getElementById('showPassword').click();d.getElementById('signin').click();await tick();assert.equal(d.getElementById('password').value,'');assert.equal(d.getElementById('signupConfirm').value,'');assert.equal(d.getElementById('password').type,'password');assert.equal(d.getElementById('showPassword').getAttribute('aria-pressed'),'false')}finally{dom.window.close()}});
test('cancel and signout discard recovery passwords and stale forms cannot update a password',async()=>{const {w,dom,event,calls}=await setup();try{const d=w.document;event('PASSWORD_RECOVERY');d.getElementById('newPassword').value='test-only-password';d.getElementById('confirmPassword').value='test-only-password';d.getElementById('cancelRecovery').click();assert.equal(d.getElementById('newPassword').value,'');assert.equal(d.getElementById('confirmPassword').value,'');d.getElementById('newPassword').value='test-only-password';d.getElementById('confirmPassword').value='test-only-password';d.getElementById('recoveryForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(calls.filter(c=>c.name==='auth:updateUser').length,0);event('PASSWORD_RECOVERY');d.getElementById('password').value='test-only-password';event('SIGNED_OUT');for(const id of ['password','signupConfirm','newPassword','confirmPassword'])assert.equal(d.getElementById(id).value,'')}finally{dom.window.close()}});

test('validated recovery and explicit account settings still allow a password change',async()=>{for(const entry of ['recovery','settings']){const {w,dom,event,calls}=await setup();try{const d=w.document;if(entry==='recovery')event('PASSWORD_RECOVERY');else d.getElementById('passwordSettings').click();d.getElementById('newPassword').value='test-only-password';d.getElementById('confirmPassword').value='test-only-password';d.getElementById('recoveryForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(calls.filter(c=>c.name==='auth:updateUser').length,1);assert.equal(d.getElementById('newPassword').value,'');assert.equal(d.getElementById('confirmPassword').value,'')}finally{dom.window.close()}}});
test('password submission stops when the verified account differs from the recovery account',async()=>{const {w,dom,event,calls,setVerifiedUser}=await setup();try{const d=w.document;event('PASSWORD_RECOVERY');setVerifiedUser({id:'another-account'});d.getElementById('newPassword').value='test-only-password';d.getElementById('confirmPassword').value='test-only-password';d.getElementById('recoveryForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(calls.filter(c=>c.name==='auth:updateUser').length,0);assert.match(d.getElementById('recoverymsg').textContent,/no longer available/)}finally{dom.window.close()}});

test('a slow profile response cannot restore a signed-out account',async()=>{const {w,dom,event,holdNextQuery}=await setup(false);try{const d=w.document,release=holdNextQuery('profiles');d.getElementById('email').value='ui@example.invalid';d.getElementById('password').value='test-only-password';d.getElementById('signin').click();await tick();event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('auth').classList.contains('active'),true);assert.equal(d.getElementById('home').classList.contains('active'),false);assert.equal(d.getElementById('myemail').textContent,'')}finally{dom.window.close()}});
test('reconciliation removes messages no longer returned by access rules',async()=>{const {w,dom,data,runReconcile}=await setup(true,true);try{const d=w.document;d.querySelector('.chatrow').click();await tick();assert.equal(d.querySelectorAll('#messages [data-message]').length,1);data.chat_messages.splice(0);await runReconcile();assert.equal(d.querySelectorAll('#messages [data-message]').length,0)}finally{dom.window.close()}});
test('signout removes private search results and all displayed account identity',async()=>{const {w,dom,event}=await setup();try{const d=w.document;d.getElementById('globalSearchResults').textContent='Private matching message';d.getElementById('globalSearchInput').value='Private query';event('SIGNED_OUT');for(const id of ['globalSearchResults','myemail','myname','roomtitle','roomsub'])assert.equal(d.getElementById(id).textContent,'');assert.equal(d.getElementById('globalSearchInput').value,'')}finally{dom.window.close()}});

test('pending room history cannot reappear after signout',async()=>{const {w,dom,event,holdNextQuery}=await setup(true,true);try{const d=w.document,release=holdNextQuery('chat_messages');d.querySelector('.chatrow').click();await tick();event('SIGNED_OUT');release();await tick();assert.equal(d.querySelectorAll('#messages [data-message]').length,0);assert.equal(d.getElementById('auth').classList.contains('active'),true)}finally{dom.window.close()}});
test('an old inbox response cannot replace the account selected in another tab',async()=>{const {w,dom,event,data,holdNextQuery,runReconcile,setVerifiedUser}=await setup();try{const release=holdNextQuery('conversation_members'),pending=runReconcile(),other={id:'99999999-9999-4999-8999-999999999999',email:'other@example.invalid'};data.profiles.push({...other,username:'other',display_name:'Other account',bio:''});setVerifiedUser(other);event('SIGNED_IN',other);await tick();release();await pending;await tick();assert.equal(w.document.getElementById('myname').textContent,'Other account');assert.equal(w.document.querySelectorAll('.chatrow').length,0)}finally{dom.window.close()}});
test('reconciliation clears an unavailable reply target and its inline quote',async()=>{const {w,dom,data,runReconcile,cid}=await setup(true,true);try{const source=data.chat_messages[0];data.chat_messages.push({...source,id:'66666666-6666-4666-8666-666666666666',body:'A reply',reply_to:source.id,reply_excerpt:'Keep me'});const d=w.document;d.querySelector('.chatrow').click();await tick();d.querySelector('[data-message="'+source.id+'"] [data-action="reply"]').click();data.chat_messages.splice(0,1);await runReconcile();assert.equal(d.getElementById('replyBar').classList.contains('hidden'),true);assert.equal(d.querySelector('.reply-quote').textContent,'Original message unavailable');assert.equal(d.querySelectorAll('#messages [data-message]').length,1)}finally{dom.window.close()}});

test('reconciliation marks through the newest fetched message while preserving older loaded history',async()=>{const {w,dom,data,runReconcile,calls}=await setup(true,true);try{const older=data.chat_messages[0],newest={...older,id:'77777777-7777-4777-8777-777777777777',body:'Newest',created_at:new Date(Date.parse(older.created_at)+1000).toISOString()};data.chat_messages.unshift(newest);w.document.querySelector('.chatrow').click();await tick();calls.length=0;await runReconcile();assert.equal(calls.filter(c=>c.name==='mark_conversation_read').at(-1).args.through_message_id,newest.id);assert.equal(w.document.querySelectorAll('#messages [data-message]').length,2)}finally{dom.window.close()}});

test('unavailable Google sign-in is absent, does not probe backend or clear local password fields',async()=>{const {w,dom,calls}=await setup(false);try{const d=w.document;d.getElementById('password').value='test-only-password';d.getElementById('signupConfirm').value='test-only-password';await tick();assert.equal(d.getElementById('googleSignIn'),null);assert.equal(d.getElementById('retryGoogleAuth'),null);assert.equal(d.getElementById('googleAuthStatus'),null);assert.equal(d.getElementById('password').value,'test-only-password');assert.equal(d.getElementById('signupConfirm').value,'test-only-password');assert.equal(calls.filter(c=>c.name==='auth:google').length,0);assert.ok(d.getElementById('signin'));assert.ok(d.getElementById('forgot'));}finally{dom.window.close()}});


async function beginSearch(t){const d=t.w.document;d.getElementById('globalSearchToggle').click();d.getElementById('globalSearchInput').value='Keep';d.getElementById('globalSearchForm').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick()}
test('closing search invalidates an outstanding private response',async()=>{const t=await setup(true,true);try{const d=t.w.document;const release=t.holdNextQuery('rpc-search');await beginSearch(t);d.getElementById('globalSearchToggle').click();release();await tick();assert.equal(d.getElementById('globalSearchResults').textContent,'');assert.equal(d.getElementById('globalSearchSubmit').disabled,false)}finally{t.dom.window.close()}});
test('a delayed search cannot return after signout and signing back into the same account',async()=>{const t=await setup(true,true);try{const d=t.w.document;const release=t.holdNextQuery('rpc-search');await beginSearch(t);t.event('SIGNED_OUT');t.event('SIGNED_IN');await tick();await tick();release();await tick();assert.equal(d.getElementById('globalSearchResults').textContent,'')}finally{t.dom.window.close()}});
test('opening an old search result never restores a message removed on the server',async()=>{const t=await setup(true,true);try{const d=t.w.document;await beginSearch(t);const result=d.querySelector('#globalSearchResults .global-result');assert.ok(result,d.getElementById('globalSearchResults').textContent);t.data.chat_messages=[];result.click();await tick();await tick();assert.doesNotMatch(d.getElementById('messages').textContent,/Keep me saved/);assert.equal(d.querySelector('[data-message="55555555-5555-4555-8555-555555555555"]'),null)}finally{t.dom.window.close()}});

test('a delayed search error cannot expose stale details after signout',async()=>{const t=await setup(true,true);try{const d=t.w.document;const release=t.holdNextQuery('rpc-search');await beginSearch(t);t.setSearchError('old account private error');t.event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('globalSearchResults').textContent,'')}finally{t.dom.window.close()}});
test('opening a search result uses the current server text instead of a cached excerpt',async()=>{const t=await setup(true,true);try{const d=t.w.document;t.w.HTMLElement.prototype.scrollIntoView=function(){};await beginSearch(t);const result=d.querySelector('#globalSearchResults .global-result');t.data.chat_messages[0].body='Current edited text';result.click();await tick();await tick();assert.match(d.getElementById('messages').textContent,/Current edited text/);assert.doesNotMatch(d.getElementById('messages').textContent,/Keep me saved/)}finally{t.dom.window.close()}});
test('message lookup completing after signout cannot repopulate the room',async()=>{const t=await setup(true,true);try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();await beginSearch(t);const release=t.holdNextQuery('chat_messages');d.querySelector('#globalSearchResults .global-result').click();await tick();t.event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('messages').textContent,'')}finally{t.dom.window.close()}});

test('delayed contact audience lookup cannot restore private names after signout',async()=>{const t=await setup();try{const d=t.w.document,release=t.holdNextQuery('rpc-contacts');d.getElementById('storyUseContacts').click();await tick();t.event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('storyAudience').value,'')}finally{t.dom.window.close()}});

test('delayed story circles cannot return across a signout and same-account signin',async()=>{const t=await setup();try{const d=t.w.document;t.data.chat_story_circles=[{id:'private-circle',owner_id:'11111111-1111-4111-8111-111111111111',name:'Private circle',usernames:['private_friend']}];const release=t.holdNextQuery('chat_story_circles');d.getElementById('newStory').click();await tick();t.event('SIGNED_OUT');t.event('SIGNED_IN');await tick();await tick();release();await tick();assert.equal(d.getElementById('storyCircle').textContent,'');assert.equal(d.getElementById('storyAudience').value,'')}finally{t.dom.window.close()}});

test('a message waiting for preparation cannot dispatch after signout',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();const release=t.holdNextQuery('translation');d.getElementById('body').value='Private unsent text';d.getElementById('sendform').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick();t.event('SIGNED_OUT');release();await tick();assert.equal(t.calls.filter(c=>c.name==='send_chat_message_idempotent').length,0);assert.equal(d.getElementById('body').disabled,false);assert.equal(d.getElementById('messages').textContent,'')}finally{t.dom.window.close()}});
test('an old send preparation cannot dispatch under a different signed-in account',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();const release=t.holdNextQuery('translation');d.getElementById('body').value='Private account A text';d.getElementById('sendform').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick();t.event('SIGNED_OUT');t.event('SIGNED_IN',{id:'22222222-2222-4222-8222-222222222222',email:'other@example.invalid'});await tick();await tick();release();await tick();assert.equal(t.calls.filter(c=>c.name==='send_chat_message_idempotent').length,0);assert.equal(d.getElementById('body').value,'')}finally{t.dom.window.close()}});

test('an old prepared send cannot dispatch after same-account reauthentication',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();const release=t.holdNextQuery('translation');d.getElementById('body').value='Before signout';d.getElementById('sendform').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick();t.event('SIGNED_OUT');t.event('SIGNED_IN');await tick();await tick();release();await tick();assert.equal(t.calls.filter(c=>c.name==='send_chat_message_idempotent').length,0)}finally{t.dom.window.close()}});
test('an old send finally block cannot unlock a newer account send',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();const releaseOld=t.holdNextQuery('translation');d.getElementById('body').value='Old private draft';d.getElementById('sendform').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick();t.event('SIGNED_OUT');t.event('SIGNED_IN',{id:'22222222-2222-4222-8222-222222222222',email:'other@example.invalid'});await tick();await tick();d.querySelector('.chatrow').click();await tick();const releaseNew=t.holdNextQuery('translation');d.getElementById('body').value='New account draft';d.getElementById('sendform').dispatchEvent(new t.w.Event('submit',{cancelable:true}));await tick();releaseOld();await tick();assert.equal(d.getElementById('body').disabled,true);assert.equal(d.getElementById('body').value,'New account draft');assert.equal(t.calls.filter(c=>c.name==='send_chat_message_idempotent').length,0);releaseNew();await tick();assert.equal(d.getElementById('body').disabled,false)}finally{t.dom.window.close()}});

test('unhandled failures do not dump arbitrary private rejection details to logs',async()=>{const t=await setup();try{const logged=[];t.w.console.error=(...args)=>logged.push(args);const event=new t.w.Event('unhandledrejection',{cancelable:true});Object.defineProperty(event,'reason',{value:{message:'private body example@example.invalid token=example-secret'}});t.w.dispatchEvent(event);assert.equal(event.defaultPrevented,true);assert.equal(JSON.stringify(logged),'[["LUO_UNHANDLED_OPERATION"]]');assert.doesNotMatch(t.w.document.getElementById('notice').textContent,/example-secret|example@example.invalid|private body/)}finally{t.dom.window.close()}});

test('Luo tools exposes the requested feature areas without requesting device access',async()=>{const{w,dom}=await setup();try{const d=w.document;d.getElementById('openLuoTools').click();assert.equal(d.getElementById('luoTools').open,true);const labels=[...d.querySelectorAll('#luoToolsBody button')].map(x=>x.textContent);for(const label of ['Your dashboard','Private chat folders','Encrypted backup / restore','Import & search chat archives','Background notifications','Voice call','Video call','Shared drawing board','Send a photo album','Accessibility','Storage manager','Connection & delivery'])assert.ok(labels.includes(label),label);assert.equal(d.getElementById('luoCall').open,false);assert.equal(d.getElementById('deviceCapture').open,false)}finally{dom.window.close()}});
test('private folders filter the inbox and changing a folder persists only owner-scoped data',async()=>{const{w,dom,data,calls,cid}=await setup();try{const d=w.document;data.chat_private_documents=[{user_id:'11111111-1111-4111-8111-111111111111',document_id:'folders',kind:'folders',title:'Private folders',payload:{folders:[{id:'family',name:'My private family',rooms:[]}]}}];d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Private chat folders').click();await tick();const filter=d.getElementById('privateFolderFilter');filter.value='family';filter.dispatchEvent(new w.Event('change'));assert.equal(d.querySelector('.chatrow').hidden,true);const box=d.querySelector('#luoToolsBody input[type=checkbox]');box.click();await tick();const saved=calls.filter(x=>x.name==='upsert:chat_private_documents').at(-1);assert.equal(saved.args.user_id,'11111111-1111-4111-8111-111111111111');assert.ok(saved.args.payload.folders[0].rooms.includes(cid))}finally{dom.window.close()}});
test('a delayed private folder response cannot restore names after signout',async()=>{const{w,dom,data,event,holdNextQuery}=await setup();try{const d=w.document;data.chat_private_documents=[{user_id:'11111111-1111-4111-8111-111111111111',document_id:'folders',kind:'folders',payload:{folders:[{id:'secret',name:'Private secret folder',rooms:[]}]}}];const release=holdNextQuery('chat_private_documents');d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Private chat folders').click();await tick();event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('luoTools').open,false);assert.equal(d.getElementById('privateFolderFilter').textContent,'All conversations');assert.equal(d.getElementById('luoToolsBody').textContent,'')}finally{dom.window.close()}});
test('quiet reading and accessibility preferences are reset when the account signs out',async()=>{const{w,dom,event}=await setup();try{const d=w.document;d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Reading position & quiet mode').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Enter quiet reading').click();assert.equal(d.body.classList.contains('quiet-reading'),true);d.getElementById('luoToolsHome').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Accessibility').click();const selects=[...d.querySelectorAll('#luoToolsBody select')];selects[1].value='reduce';selects[2].value='high';[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Save accessibility preferences').click();assert.equal(d.body.classList.contains('luo-reduced-motion'),true);assert.equal(d.body.classList.contains('luo-high-contrast'),true);event('SIGNED_OUT');for(const cls of ['quiet-reading','luo-reduced-motion','luo-high-contrast'])assert.equal(d.body.classList.contains(cls),false)}finally{dom.window.close()}});

test('dashboard filters pending owner items before applying query limits',async()=>{const t=await setup();try{const d=t.w.document,owner='11111111-1111-4111-8111-111111111111';t.data.chat_reminders=[...Array.from({length:110},()=>({user_id:owner,title:'Dismissed reminder',dismissed_at:'2026-01-01'})),{user_id:owner,title:'Actual upcoming reminder',dismissed_at:null,remind_at:'2027-01-01T09:00:00Z'}];t.data.chat_group_tasks=[...Array.from({length:110},()=>({assigned_to:'other',title:'Another persons task',completed_at:null})),{assigned_to:owner,title:'Actual assigned task',completed_at:null}];t.data.scheduled_messages=[...Array.from({length:110},()=>({sender_id:owner,status:'sent',body:'Past schedule'})),{sender_id:owner,status:'pending',body:'Actual pending schedule',send_at:'2027-01-01T09:00:00Z'}];d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Your dashboard').click();await tick();const text=d.getElementById('luoToolsBody').textContent;for(const expected of ['Actual upcoming reminder','Actual assigned task','Actual pending schedule'])assert.ok(text.includes(expected),expected);assert.doesNotMatch(text,/Dismissed reminder|Another persons task|Past schedule/)}finally{t.dom.window.close()}});

function archiveControls(t){const d=t.w.document;d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Import & search chat archives').click();return{file:d.querySelector('#luoToolsBody input[type=file]'),order:d.querySelector('#luoToolsBody select'),preview:[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Preview import'),save:[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent==='Import previewed messages privately'),status:d.getElementById('luoToolsStatus')}};
function chooseArchive(t,input,text){const file={size:100,text:()=>typeof text==='string'?Promise.resolve(text):text};Object.defineProperty(input,'files',{value:[file],configurable:true});input.dispatchEvent(new t.w.Event('change'));return file}
test('changing archive date order invalidates the preview before private import',async()=>{const t=await setup();try{const c=archiveControls(t);t.w.confirm=()=>true;chooseArchive(t,c.file,'01/02/2026, 10:20 - Alex: Previewed body');c.preview.click();await tick();assert.match(c.status.textContent,/1 messages found/);c.order.value='month';c.order.dispatchEvent(new t.w.Event('change'));c.save.click();await tick();assert.equal(t.calls.filter(x=>x.name==='upsert:chat_private_documents').length,0);assert.match(t.w.document.getElementById('notice').textContent,/Preview the export first/)}finally{t.dom.window.close()}});
test('a failed replacement archive preview cannot import the previous file',async()=>{const t=await setup();try{const c=archiveControls(t);t.w.confirm=()=>true;chooseArchive(t,c.file,'01/02/2026, 10:20 - Alex: Old body');c.preview.click();await tick();chooseArchive(t,c.file,'Unsupported replacement file');c.preview.click();await tick();c.save.click();await tick();assert.equal(t.calls.filter(x=>x.name==='upsert:chat_private_documents').length,0);assert.doesNotMatch(t.w.document.getElementById('luoToolsBody').textContent,/Old body/)}finally{t.dom.window.close()}});
test('an archive file read finishing after the selection changes cannot restore a stale preview',async()=>{const t=await setup();let release;try{const c=archiveControls(t);t.w.confirm=()=>true;chooseArchive(t,c.file,new Promise(r=>release=r));c.preview.click();await tick();chooseArchive(t,c.file,'01/02/2026, 10:20 - Alex: New body');release('01/02/2026, 10:20 - Alex: Late private body');await tick();c.save.click();await tick();assert.equal(t.calls.filter(x=>x.name==='upsert:chat_private_documents').length,0);assert.doesNotMatch(t.w.document.getElementById('luoToolsBody').textContent,/Late private body/)}finally{release?.('');t.dom.window.close()}});
test('conversation actions close on Escape and return focus to the menu summary',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();const menu=d.getElementById('roomMenu');menu.querySelector('summary').tabIndex=0;menu.open=true;d.dispatchEvent(new t.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));assert.equal(menu.open,false);assert.equal(d.activeElement,menu.querySelector('summary'));assert.ok([...menu.querySelectorAll('button')].some(b=>b.textContent==='Schedule this message'))}finally{t.dom.window.close()}});
test('feedback from a tool action is visible inside its modal dialog',async()=>{const t=await setup();try{const d=t.w.document;d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(b=>b.textContent==='Background notifications').click();await tick();[...d.querySelectorAll('#luoToolsBody button')].find(b=>b.textContent==='Enable on this device').click();await tick();const feedback=d.querySelector('#luoTools .dialog-feedback');assert.ok(feedback);assert.match(feedback.textContent,/unavailable/);assert.equal(feedback.getAttribute('role'),'status')}finally{t.dom.window.close()}});
test('all generated dialogs have an accessible name linked to a live heading',async()=>{const t=await setup();try{const d=t.w.document;for(const dialog of d.querySelectorAll('dialog')){const ids=(dialog.getAttribute('aria-labelledby')||'').split(/\s+/).filter(Boolean);assert.ok(dialog.getAttribute('aria-label')||ids.length,'Unnamed dialog '+dialog.id);for(const id of ids)assert.ok(d.getElementById(id)?.textContent.trim(),'Missing dialog title '+id)}}finally{t.dom.window.close()}});
test('a stale room channel cannot replace the connection state after signout',async()=>{const t=await setup();try{const d=t.w.document;d.querySelector('.chatrow').click();await tick();t.event('SIGNED_OUT');const before=d.getElementById('state').textContent;t.channelStatus(0,'SUBSCRIBED');assert.equal(d.getElementById('state').textContent,before)}finally{t.dom.window.close()}});
test('contact lookup finishing after signout cannot restore an old result',async()=>{const t=await setup();let release;try{const d=t.w.document;d.getElementById('target').value='friend';release=t.holdNextQuery('rpc-lookup');d.getElementById('lookup').click();await tick();t.event('SIGNED_OUT');release();await tick();assert.equal(d.getElementById('lookupResult').textContent,'');assert.equal(d.getElementById('lookup').disabled,false);assert.equal(d.getElementById('saveContact').classList.contains('hidden'),true)}finally{release?.();t.dom.window.close()}});
test('editing a username invalidates pending lookup results and permits a fresh lookup',async()=>{const t=await setup();let release;try{const d=t.w.document,target=d.getElementById('target');target.value='friend';release=t.holdNextQuery('rpc-lookup');d.getElementById('lookup').click();await tick();target.value='someone_else';target.dispatchEvent(new t.w.Event('input',{bubbles:true}));assert.equal(d.getElementById('lookup').disabled,false);release();await tick();assert.equal(d.getElementById('lookupResult').textContent,'');assert.equal(d.getElementById('saveContact').classList.contains('hidden'),true)}finally{release?.();t.dom.window.close()}});

function suitePage(t,label){const d=t.w.document;d.getElementById('openLuoTools').click();[...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent===label).click();return d}
function suiteButton(d,label){return [...d.querySelectorAll('#luoToolsBody button')].find(x=>x.textContent===label)}
test('folder edits serialize against confirmed state instead of losing another checkbox change',async()=>{const t=await setup();try{const owner='11111111-1111-4111-8111-111111111111';t.data.chat_private_documents=[{user_id:owner,kind:'folders',document_id:'folders',payload:{folders:[{id:'a',name:'First',rooms:[]},{id:'b',name:'Second',rooms:[]}]}}];const d=suitePage(t,'Private chat folders');await tick();const boxes=[...d.querySelectorAll('#luoToolsBody input[type=checkbox]')];assert.equal(boxes.length,2);const release=t.holdNextQuery('chat_private_documents');boxes[0].click();await tick();boxes[1].click();await tick();let writes=t.calls.filter(x=>x.name==='upsert:chat_private_documents');assert.equal(writes.length,1);release();await tick();await tick();writes=t.calls.filter(x=>x.name==='upsert:chat_private_documents');assert.equal(writes.length,2);assert.deepEqual(writes[1].args.payload.folders.map(x=>[...x.rooms]),[[t.cid],[t.cid]])}finally{t.dom.window.close()}});
test('queued folder edits are cancelled after signout',async()=>{const t=await setup();try{const owner='11111111-1111-4111-8111-111111111111';t.data.chat_private_documents=[{user_id:owner,kind:'folders',document_id:'folders',payload:{folders:[{id:'a',name:'First',rooms:[]},{id:'b',name:'Second',rooms:[]}]}}];const d=suitePage(t,'Private chat folders');await tick();const boxes=d.querySelectorAll('#luoToolsBody input[type=checkbox]'),release=t.holdNextQuery('chat_private_documents');boxes[0].click();await tick();boxes[1].click();await tick();await t.event('SIGNED_OUT',null);release();await tick();await tick();assert.equal(t.calls.filter(x=>x.name==='upsert:chat_private_documents').length,1);assert.equal(d.getElementById('luoToolsStatus').textContent,'')}finally{t.dom.window.close()}});
test('backup export uses the submitted password while history is loading',async()=>{const {webcrypto}=await import('node:crypto'),{decryptBackup}=await import('../src/archive-utils.js');const t=await setup();try{const w=t.w;Object.defineProperty(w.crypto,'subtle',{value:webcrypto.subtle});let encoded;w.Blob=class{constructor(parts){encoded=parts.join('')}};w.URL.createObjectURL=()=> 'blob:test';w.URL.revokeObjectURL=()=>{};w.HTMLAnchorElement.prototype.click=function(){};w.document.querySelector('.chatrow').click();await tick();const d=suitePage(t,'Encrypted backup / restore');await tick();const fields=d.querySelectorAll('#luoToolsBody input[type=password]');fields[0].value=fields[1].value='original-password-123';const release=t.holdNextQuery('chat_messages');suiteButton(d,'Export encrypted backup').click();await tick();fields[0].value=fields[1].value='changed-password-456';release();for(let i=0;i<300&&!encoded;i++)await tick();assert.ok(encoded,'encrypted download created');const decoded=await decryptBackup(encoded,'original-password-123',webcrypto);assert.equal(decoded.format,'luo-snapshot');await assert.rejects(decryptBackup(encoded,'changed-password-456',webcrypto),/Wrong password/)}finally{t.dom.window.close()}});
test('restore and export cannot run concurrently',async()=>{const t=await setup();try{const d=suitePage(t,'Encrypted backup / restore');await tick();let release;const held=new Promise(r=>release=r),fields=d.querySelectorAll('#luoToolsBody input[type=password]');fields[0].value=fields[1].value='valid-password-123';const file=d.querySelector('#luoToolsBody input[type=file]');Object.defineProperty(file,'files',{value:[{size:100,text:()=>held}]});suiteButton(d,'Decrypt and restore private copies').click();await tick();suiteButton(d,'Export encrypted backup').click();await tick();assert.match(d.getElementById('luoTools').textContent,/Another backup operation/);release('invalid');await tick()}finally{t.dom.window.close()}});
test('notification status cannot overwrite a different tools page after a delayed browser response',async()=>{const t=await setup();try{let release;const held=new Promise(r=>release=r);t.w.PushManager=function(){};Object.defineProperty(t.w.navigator,'serviceWorker',{configurable:true,value:{getRegistration:()=>held}});const d=suitePage(t,'Background notifications');await tick();d.getElementById('luoToolsHome').click();release(null);await tick();assert.equal(d.getElementById('luoToolsTitle').textContent,'Luo tools');assert.equal(d.getElementById('luoToolsStatus').textContent,'')}finally{t.dom.window.close()}});
test('old tools failures do not display feedback in a later session',async()=>{const t=await setup();try{const d=suitePage(t,'Encrypted backup / restore');await tick();let release;const held=new Promise(r=>release=r),file=d.querySelector('#luoToolsBody input[type=file]');Object.defineProperty(file,'files',{value:[{size:100,text:()=>held}]});d.querySelector('#luoToolsBody input[type=password]').value='valid-password-123';suiteButton(d,'Decrypt and restore private copies').click();await tick();await t.event('SIGNED_OUT',null);release('invalid');await tick();assert.doesNotMatch(d.getElementById('notice').textContent,/Invalid backup/)}finally{t.dom.window.close()}});

test('background message reconciliation does not poll while settings replaces the chat screen',async()=>{const t=await setup();try{t.w.document.querySelector('[data-tab="profile"]').click();await tick();t.calls.length=0;await t.runReconcile();assert.equal(t.calls.some(x=>['get_my_chat_previews','get_my_conversation_unread_counts','get_chat_message_extras','set_chat_presence'].includes(x.name)),false)}finally{t.dom.window.close()}});

test('a burst of 20 actual inbox realtime events coalesces to two backend reloads',async()=>{const t=await setup();try{t.calls.length=0;const release=t.holdNextQuery('conversation_members'),message={id:'burst',conversation_id:t.cid,sender_id:'friend',body:'Burst',created_at:new Date().toISOString()};const first=t.emitInbox(message);await tick();const rest=Array.from({length:20},()=>t.emitInbox(message));await tick();release();await Promise.all([first,...rest]);assert.equal(t.calls.filter(x=>x.name==='select:conversation_members'&&x.args==='conversation_id,role,last_read_at,muted').length,2);assert.equal(t.calls.filter(x=>x.name==='get_my_chat_previews').length,2);assert.equal(t.calls.filter(x=>x.name==='get_my_conversation_unread_counts').length,2)}finally{t.dom.window.close()}});


test('a Supabase gateway timeout on sign-in is not falsely reported as bad credentials',async()=>{
 const {w,dom,setSignInFailure}=await setup(false,false,null,'https://luo-chat-luokai25.vercel.app/',{signInFailure:{status:504,message:'context deadline exceeded'}});
 const d=w.document;
 d.getElementById('email').value='ui@example.invalid';
 d.getElementById('password').value='correct-password';
 d.getElementById('signin').click();await tick();await tick();
 assert.ok(d.getElementById('auth').classList.contains('active'));
 assert.match(d.getElementById('authmsg').textContent,/temporarily unavailable/);
 assert.equal(d.getElementById('password').value,'correct-password','transient failure must preserve the credential input for manual retry');
 assert.equal(d.getElementById('signin').disabled,false);
 setSignInFailure(null);
 d.getElementById('signin').click();await tick();await tick();
 assert.ok(d.getElementById('home').classList.contains('active'),'manual retry should recover after service comes back');
 dom.window.close();
});
test('failed refresh leaves an explicit retry control and restores the previous session without a new password',async()=>{
 const {w,dom,setSessionFailure,setSessionAvailable}=await setup(true,false,null,'https://luo-chat-luokai25.vercel.app/',{sessionFailure:{status:500,message:'error finding refresh token: context canceled'}});
 const d=w.document,button=d.getElementById('retryAuthRestore');
 assert.ok(d.getElementById('auth').classList.contains('active'));
 assert.match(d.getElementById('authmsg').textContent,/saved session may still be valid/);
 assert.equal(button.hidden,false);
 setSessionFailure(null);setSessionAvailable(true);
 button.click();await tick();await tick();
 assert.ok(d.getElementById('home').classList.contains('active'));
 assert.equal(d.getElementById('password').value,'');
 assert.equal(button.hidden,true);
 dom.window.close();
});
test('a successful auth session with a temporary profile outage never claims invalid credentials',async()=>{
 const {w,dom,setProfileFailure}=await setup(true,false,null,'https://luo-chat-luokai25.vercel.app/',{profileFailure:{status:504,message:'database timeout'}});
 const d=w.document;
 assert.ok(d.getElementById('auth').classList.contains('active'));
 assert.match(d.getElementById('authmsg').textContent,/saved session may still be valid/);
 setProfileFailure(null);
 d.getElementById('retryAuthRestore').click();await tick();await tick();
 assert.ok(d.getElementById('home').classList.contains('active'));
 dom.window.close();
});


test('a newer successful SIGNED_IN supersedes an earlier hung account restoration',async()=>{
 const {w,dom,holdNextQuery,event}=await setup(false);
 const release=holdNextQuery('profiles');
 event('SIGNED_IN');await tick();
 event('SIGNED_IN');await tick();await tick();
 assert.ok(w.document.getElementById('home').classList.contains('active'),'fresh sign-in must not be ignored by an earlier pending boot');
 release();await tick();await tick();
 assert.ok(w.document.getElementById('home').classList.contains('active'),'older restore may not replace active session');
 dom.window.close();
});

test('manual password sign-in clears a stale startup outage warning immediately',async()=>{
 const {w,dom,setSessionFailure}=await setup(true,false,null,'https://luo-chat-luokai25.vercel.app/',{sessionFailure:{status:504,message:'context deadline exceeded'}});
 const d=w.document;
 assert.match(d.getElementById('authmsg').textContent,/cannot reach/);
 setSessionFailure(null);
 d.getElementById('email').value='ui@example.invalid';
 d.getElementById('password').value='right-password';
 d.getElementById('signin').click();await tick();await tick();
 assert.ok(d.getElementById('home').classList.contains('active'));
 assert.equal(d.getElementById('authmsg').textContent,'');
 dom.window.close();
});


test('authentication tabs and keyboard Enter work without exposing hidden signup controls',async()=>{
 const {w,dom}=await setup(false);const d=w.document;
 assert.ok(d.getElementById('signin')&&!d.getElementById('signin').classList.contains('hidden'));
 assert.equal(d.getElementById('authModeSignin').getAttribute('aria-pressed'),'true');
 assert.equal(d.getElementById('authModeSignup').getAttribute('aria-pressed'),'false');
 d.getElementById('authModeSignup').click();
 assert.equal(d.getElementById('authHeading').textContent,'Create your space.');
 assert.equal(d.getElementById('authModeSignup').getAttribute('aria-pressed'),'true');
 assert.equal(d.getElementById('username').classList.contains('hidden'),false);
 assert.equal(d.getElementById('forgot').hidden,true);
 assert.match(d.getElementById('loginMethodNote').textContent,/email confirmation/i);
 d.getElementById('authModeSignin').click();
 assert.equal(d.getElementById('forgot').hidden,false);
 assert.equal(d.getElementById('signup').classList.contains('hidden'),true);
 d.getElementById('email').value='ui@example.invalid';
 d.getElementById('password').value='long-password';
 const press=new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true});
 d.getElementById('password').dispatchEvent(press);
 assert.equal(press.defaultPrevented,true);
 await tick();await tick();
 assert.ok(d.getElementById('home').classList.contains('active'),'Enter signs in via existing Supabase password flow');
 dom.window.close();
});
test('auth surface tells users their actual login method and has safe, labelled focus targets',async()=>{
 const {w,dom}=await setup(false);const d=w.document;
 assert.ok(d.querySelector('link[href="/luo-auth-premium.css"]'));
 assert.equal(d.getElementById('email').getAttribute('type'),'email');
 assert.match(d.getElementById('loginMethodNote').textContent,/existing accounts/i);
 assert.ok(d.getElementById('authHeading'));
 assert.ok(d.getElementById('authSubheading'));
 assert.ok(d.querySelector('.luo-access-brand img'));
 assert.equal(d.getElementById('authmsg').getAttribute('role'),'status');
 assert.ok(d.getElementById('forgot'));
 assert.ok(d.getElementById('resend'));
 assert.equal(d.getElementById('googleSignIn'),null);
 dom.window.close();
});
